        public byte[] CreateGndFile(List<MapGridPart> blocks)
        {
            using (var ms = new MemoryStream())
            using (var bw = new BinaryWriter(ms))
            {
                byte[] textures = GetTexturesBlock();
                byte[] settings = SettingsHeader;

                int currentStart = textures.Length + settings.Length;
                
                var blockInfos = new List<(MapGridPart Part, byte[] TileData, byte[] ImageData, int Start, int ImageStart)>();
                
                foreach (var block in blocks)
                {
                    byte[] tileData = block.GetTileData(0);
                    byte[] imageData = block.GetPreviewImageData();
                    
                    blockInfos.Add((block, tileData, imageData, currentStart, currentStart + tileData.Length));
                    currentStart += tileData.Length + imageData.Length;
                }

                byte[] header = GetBlockTable(blockInfos);

                bw.Write(header);
                bw.Write(settings);
                bw.Write(textures);

                foreach (var info in blockInfos)
                {
                    bw.Write(info.TileData);
                    bw.Write(info.ImageData);
                }

                return ms.ToArray();
            }
        }

        private byte[] GetTexturesBlock()
        {
            using (var ms = new MemoryStream())
            using (var bw = new BinaryWriter(ms))
            {
                bw.Write(TEXTURE_COUNT);
                for (int i = 0; i < TEXTURE_COUNT; i++)
                {
                    if (i == 0)
                    {
                        // Default Auran Grid texture
                        bw.Write(1.0f); // usage
                        bw.Write(10014); // kuid part 2
                        bw.Write(-3); // kuid part 1
                    }
                    else
                    {
                        bw.Write(0.0f); // usage
                        bw.Write(0); // kuid part 2
                        bw.Write(0); // kuid part 1
                    }
                }
                return ms.ToArray();
            }
        }

        private byte[] GetBlockTable(List<(MapGridPart Part, byte[] TileData, byte[] ImageData, int Start, int ImageStart)> blocks)
        {
            using (var ms = new MemoryStream())
            using (var bw = new BinaryWriter(ms))
            {
                bw.Write((byte)'G');
                bw.Write((byte)'N');
                bw.Write((byte)'D');
                bw.Write((byte)0x0b);
                
                bw.Write(blocks.Count);

                int headerSize = 8 + 16 * blocks.Count; // GND\x0b + count + (16 bytes per block)

                foreach (var block in blocks)
                {
                    bw.Write(block.Part.SegmentX);
                    bw.Write(block.Part.SegmentY);
                    bw.Write(headerSize + block.Start);
                    bw.Write(headerSize + block.ImageStart);
                }

                return ms.ToArray();
            }
        }
    }
